import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Filters, Pager, Pairs, Select, TextInput, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 10;

const TYPES: [string, string][] = [
  ['NOTE', '쪽지'],
  ['CHAT', '대화방 메시지'],
  ['MAIL', '메일'],
];

export default function FnSfr03605Page({ role, notify }: PageProps) {
  const [messageType, setMessageType] = useState('');
  const [attachmentTitle, setAttachmentTitle] = useState('');
  const [userName, setUserName] = useState('');
  const [applied, setApplied] = useState({ messageType: '', attachmentTitle: '', userName: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/messages', role, undefined, {
      messageType: applied.messageType,
      attachmentTitle: applied.attachmentTitle,
      userName: applied.userName,
      page,
      size: SIZE,
    }),
    [role, applied, page],
  );

  const items = data ? data.items : [];
  const total = data ? data.total : 0;

  const search = () => {
    setPage(0);
    setApplied({ messageType, attachmentTitle, userName });
  };

  const reset = () => {
    setMessageType('');
    setAttachmentTitle('');
    setUserName('');
    setPage(0);
    setApplied({ messageType: '', attachmentTitle: '', userName: '' });
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 현황</h2>
        <Tiles items={[
          ['조회된 메시지', total],
          ['현재 쪽', page + 1],
        ]} />
      </section>
      <section className="box span-8">
        <h2>내 메시지</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="메시지 유형">
            <Select value={messageType} onChange={setMessageType} options={TYPES} placeholder="전체" />
          </Field>
          <Field label="파일명">
            <TextInput value={attachmentTitle} onChange={setAttachmentTitle} />
          </Field>
          <Field label="성명">
            <TextInput value={userName} onChange={setUserName} />
          </Field>
        </Filters>
        <Band total={total} />
        {error ? <div>{error}</div> : null}
        {loading ? <div>불러오는 중입니다.</div> : null}
        <DataTable
          columns={[
            { key: 'messageType', label: '메시지 유형', render: (r) => <Badge value={r.messageType} /> },
            { key: 'subject', label: '제목' },
            { key: 'senderName', label: '성명' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r.sentAt} time /> },
          ]}
          rows={items}
          onRowClick={(r) => setSelected(r)}
          empty="조회된 메시지가 없습니다."
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>최근 내역</h2>
        <DataTable
          columns={[
            { key: 'senderName', label: '성명' },
            { key: 'sentAt', label: '발송 일시', render: (r) => <DateText value={r.sentAt} time /> },
          ]}
          rows={items.slice(0, 5)}
          onRowClick={(r) => setSelected(r)}
          empty="최근 메시지가 없습니다."
        />
      </section>
      {selected ? (
        <Drawer title="메시지 상세" onClose={() => setSelected(null)}>
          <Pairs items={[
            ['메시지 유형', <Badge value={selected.messageType} />],
            ['제목', String(selected.subject ?? '')],
            ['성명', String(selected.senderName ?? '')],
            ['발송 일시', <DateText value={selected.sentAt} time />],
            ['메시지 내용', String(selected.content ?? '')],
          ]} />
        </Drawer>
      ) : null}
    </div>
  );
}
